const HIDE_ATTR = 'data-dar-claw-hide'
const TREE_HIDE_ATTR = 'data-dar-tree-hide'
const ZONE_HIDE_ATTR = 'data-dar-zone-hide'
const ZONE_ATTR = 'data-dar-zone-switch'
const CLAW_ACTIONS_ATTR = 'data-dar-claw-actions'
const SEARCH_HIDE_ATTR = 'data-dar-search-hide'

